from pathlib import Path
p=Path('index.html')
s=p.read_text()

def replace_once(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'{label} not found')
    s=s.replace(old,new,1)

# Add full-screen Words overrides after the existing Words responsive block.
anchor="""@media(min-width:900px),(max-height:500px) and (orientation:landscape){#wordsPage.active{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto 1fr auto auto auto;gap:7px 50px;padding-left:max(24px,calc((100% - 840px)/2));padding-right:max(24px,calc((100% - 840px)/2))}#wordsPage .game-heading{grid-column:1/-1}#wordsPage .word-targets{grid-column:1;grid-row:2/6;--tile:clamp(28px,7dvh,60px)}#wordsPage .word-status{grid-column:2;align-self:end}#wordsPage .word-selection-row{grid-column:2}#wordsPage .word-wheel-wrap{grid-column:2;--wheel:min(300px,40dvh)}#wordsPage .word-gesture-hint,#wordsPage #nextWord{grid-column:2}}\n"""
overrides="""@media(min-width:900px),(max-height:500px) and (orientation:landscape){#wordsPage.active{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto 1fr auto auto auto;gap:7px 50px;padding-left:max(24px,calc((100% - 840px)/2));padding-right:max(24px,calc((100% - 840px)/2))}#wordsPage .game-heading{grid-column:1/-1}#wordsPage .word-targets{grid-column:1;grid-row:2/6;--tile:clamp(28px,7dvh,60px)}#wordsPage .word-status{grid-column:2;align-self:end}#wordsPage .word-selection-row{grid-column:2}#wordsPage .word-wheel-wrap{grid-column:2;--wheel:min(300px,40dvh)}#wordsPage .word-gesture-hint,#wordsPage #nextWord{grid-column:2}}\n\n/* Words-only full-screen layout, matching Snake game-page treatment */\nbody:has(#wordsPage.active) .topbar{display:none}\nbody:has(#wordsPage.active) #app{min-height:100dvh}\n#wordsPage{height:100dvh;min-height:0;max-width:none;padding:max(10px,env(safe-area-inset-top)) 14px max(8px,env(safe-area-inset-bottom));overflow:hidden;background:#fff radial-gradient(circle,#d6e0fb 1.15px,transparent 1.45px);background-size:28px 28px}\n#wordsPage.active{display:flex;flex-direction:column;gap:5px}\n#wordsPage .game-heading{flex:0 0 auto;width:100%;margin:0;padding:2px 0 4px;grid-template-columns:44px minmax(0,1fr) auto;gap:12px}\n#wordsPage .word-label-row{display:flex;align-items:center;gap:9px;min-height:22px}\n#wordsPage .word-label-row .eyebrow{margin:0}\n#wordsPage .word-sound{width:30px;height:30px;border:0;background:#f3f6fc;border-radius:50%;display:grid;place-items:center;font-size:14px;cursor:pointer;padding:0}\n#wordsPage .word-head-stats{display:flex;gap:13px;align-items:center;text-align:right}\n#wordsPage .word-head-stats span{display:flex;flex-direction:column;align-items:flex-end;min-width:48px}\n#wordsPage .word-head-stats b{font-size:18px;color:#3568ee;line-height:1.05}\n#wordsPage .word-head-stats small{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:#9aa5b8}\n#wordsPage .word-targets{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:clamp(8px,1.2dvh,14px);margin:0;padding:8px 0;--tile:clamp(40px,6.3dvh,58px)}\n#wordsPage .word-target{gap:clamp(7px,1vw,10px)}\n#wordsPage .word-status{flex:0 0 auto;display:flex;flex-direction:row;justify-content:center;gap:14px;padding:2px 8px;background:rgba(255,255,255,.84);min-height:24px}\n#wordsPage .word-selection-row{flex:0 0 auto;min-height:42px;margin:0}\n#wordsPage .word-wheel-wrap{flex:0 0 auto;--wheel:min(360px,38dvh,calc(100vw - 76px));height:var(--wheel);margin:2px auto 0}\n#wordsPage .word-wheel,#wordsPage .word-lines{width:var(--wheel);height:var(--wheel)}\n#wordsPage .letter{min-width:50px;min-height:50px;font-size:clamp(29px,4.6dvh,42px)}\n#wordsPage .round-tool{top:50%;width:54px;height:66px}\n#wordsPage .word-gesture-hint{flex:0 0 auto;margin:2px 0 0;min-height:17px}\n#wordsPage #nextWord{margin:8px auto 8px}\n@media(max-width:760px){#wordsPage{height:100dvh;padding:max(7px,env(safe-area-inset-top)) 12px max(5px,env(safe-area-inset-bottom))}#wordsPage .game-heading h1{font-size:25px}#wordsPage .word-targets{--tile:clamp(38px,5.8dvh,54px)}#wordsPage .word-wheel-wrap{--wheel:min(350px,37dvh,calc(100vw - 68px))}#wordsPage .word-head-stats{gap:9px}#wordsPage .word-head-stats span{min-width:42px}}\n@media(max-height:700px) and (orientation:portrait){#wordsPage .word-targets{--tile:clamp(30px,4.8dvh,40px);gap:5px;padding:3px 0}#wordsPage .word-wheel-wrap{--wheel:min(280px,31dvh,calc(100vw - 78px))}#wordsPage .word-selection-row{min-height:34px}#wordsPage .word-status{min-height:20px;font-size:9px}#wordsPage .word-gesture-hint{display:none}}\n@media(min-width:900px),(max-height:500px) and (orientation:landscape){#wordsPage.active{display:grid;grid-template-columns:minmax(0,1fr) minmax(330px,460px);grid-template-rows:auto 1fr auto auto;gap:6px 42px;padding-left:max(20px,calc((100% - 920px)/2));padding-right:max(20px,calc((100% - 920px)/2))}#wordsPage .game-heading{grid-column:1/-1}#wordsPage .word-targets{grid-column:1;grid-row:2/5;--tile:clamp(32px,7dvh,58px)}#wordsPage .word-status{grid-column:2;grid-row:2;align-self:end}#wordsPage .word-selection-row{grid-column:2;grid-row:3}#wordsPage .word-wheel-wrap{grid-column:2;grid-row:4;--wheel:min(360px,48dvh)}#wordsPage .word-gesture-hint,#wordsPage #nextWord{grid-column:2}}\n"""
replace_once(anchor,overrides,'Words responsive anchor')

old_heading='''        <div><p class="eyebrow">WORDS</p><h1>Level <span id="wordLevel">1</span> <small>/ 1000</small></h1></div>\n        <div class="heading-stat"><b id="wordFoundCount">0/4</b><span>found</span></div>'''
new_heading='''        <div><div class="word-label-row"><p class="eyebrow">WORDS</p><button id="wordSoundButton" class="word-sound" aria-label="Toggle sound">♪</button></div><h1>Level <span id="wordLevel">1</span> <small>/ 1000</small></h1></div>\n        <div class="word-head-stats"><span><b id="wordFoundCount">0/4</b><small>found</small></span><span><b id="wordPoints">100</b><small>pts</small></span></div>'''
replace_once(old_heading,new_heading,'Words heading')

old_sync="function syncSoundButtons(){$('soundButton').textContent=sound?'♫':'♪';const sb=$('snakeSoundButton');if(sb)sb.textContent=sound?'♫':'♪'}\nsyncSoundButtons();$('soundButton').addEventListener('click',()=>{sound=!sound;storage.set('sound',sound);syncSoundButtons();beep()});$('snakeSoundButton').addEventListener('click',()=>{sound=!sound;storage.set('sound',sound);syncSoundButtons();beep()});"
new_sync="function syncSoundButtons(){$('soundButton').textContent=sound?'♫':'♪';const sb=$('snakeSoundButton');if(sb)sb.textContent=sound?'♫':'♪';const wb=$('wordSoundButton');if(wb)wb.textContent=sound?'♫':'♪'}\nsyncSoundButtons();$('soundButton').addEventListener('click',()=>{sound=!sound;storage.set('sound',sound);syncSoundButtons();beep()});$('snakeSoundButton').addEventListener('click',()=>{sound=!sound;storage.set('sound',sound);syncSoundButtons();beep()});$('wordSoundButton').addEventListener('click',()=>{sound=!sound;storage.set('sound',sound);syncSoundButtons();beep()});"
replace_once(old_sync,new_sync,'Sound sync')

old_render="$('wordLevel').textContent=wordGame.levelIndex+1;$('globalPoints').textContent=wordGame.score;$('wordFoundCount').textContent=wordGame.found.length+'/'+wordGame.level.targets.length;$('bonusCount').textContent=wordGame.extras.length+' bonus word'+(wordGame.extras.length===1?'':'s');$('hintCost').textContent='−'+hintCost(wordGame.hintsUsed);"
new_render="$('wordLevel').textContent=wordGame.levelIndex+1;$('globalPoints').textContent=wordGame.score;$('wordPoints').textContent=wordGame.score;$('wordFoundCount').textContent=wordGame.found.length+'/'+wordGame.level.targets.length;$('bonusCount').textContent=wordGame.extras.length+' bonus word'+(wordGame.extras.length===1?'':'s');const currentHintWord=wordGame.level.targets.find(w=>!wordGame.found.includes(w));const currentHintStep=currentHintWord?(wordGame.revealed[currentHintWord]||0):0;$('hintCost').textContent='−'+hintCost(currentHintStep);"
replace_once(old_render,new_render,'Words render hint cost')

old_hint="hint(){if(this.status!=='playing')return{type:'none'};const cost=hintCost(this.hintsUsed);if(this.score<cost)return{type:'points',cost};const word=this.level.targets.find(w=>!this.found.includes(w));if(!word)return{type:'none'};const n=this.revealed[word]||0;this.score-=cost;this.hintsUsed++;this.revealed[word]=Math.min(word.length,n+1);if(this.revealed[word]>=word.length){this.found.push(word);this.check()}return{type:'hint',word,index:n,letter:word[n],cost,nextCost:hintCost(this.hintsUsed)}}"
new_hint="hint(){if(this.status!=='playing')return{type:'none'};const word=this.level.targets.find(w=>!this.found.includes(w));if(!word)return{type:'none'};const n=this.revealed[word]||0,cost=hintCost(n);if(this.score<cost)return{type:'points',cost};this.score-=cost;this.revealed[word]=Math.min(word.length,n+1);if(this.revealed[word]>=word.length){this.found.push(word);this.check()}const nextWord=this.level.targets.find(w=>!this.found.includes(w));const nextStep=nextWord?(this.revealed[nextWord]||0):0;return{type:'hint',word,index:n,letter:word[n],cost,nextCost:hintCost(nextStep)}}"
replace_once(old_hint,new_hint,'Per-word hint logic')

p.write_text(s)
print('Words full-screen + per-word hint patch applied')
